-- Phase 54: governed clinical-service catalogue. Reads or changes no patient-authored record.
START TRANSACTION;
CREATE TABLE IF NOT EXISTS ilb_clinical_service_catalog (
 service_key varchar(80) NOT NULL, display_order smallint unsigned NOT NULL, service_name varchar(180) NOT NULL,
 service_group varchar(80) NOT NULL, primary_inputs varchar(1200) NOT NULL, timeline_output varchar(1000) NOT NULL,
 review_boundary varchar(1500) NOT NULL, status enum('draft','active','retired') NOT NULL DEFAULT 'active',
 PRIMARY KEY(service_key), UNIQUE KEY uq_ilb_service_catalog_order(display_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ON DUPLICATE KEY UPDATE display_order=VALUES(display_order),service_name=VALUES(service_name),service_group=VALUES(service_group),primary_inputs=VALUES(primary_inputs),timeline_output=VALUES(timeline_output),review_boundary=VALUES(review_boundary),status=VALUES(status);
ON DUPLICATE KEY UPDATE object_type=VALUES(object_type),domain_key=VALUES(domain_key),canonical_role=VALUES(canonical_role),frontend_access=VALUES(frontend_access),lifecycle_status=VALUES(lifecycle_status),replacement_object_name=VALUES(replacement_object_name),decision_note=VALUES(decision_note),release_key=VALUES(release_key);
CREATE OR REPLACE VIEW v_ilb_clinical_service_catalog AS SELECT service_key,display_order,service_name,service_group,primary_inputs,timeline_output,review_boundary FROM ilb_clinical_service_catalog WHERE status='active' ORDER BY display_order;
COMMIT;